cd /home/judge/solution && export DITTO_PASSWORD=$(grep ^DITTO_PASSWORD= deploy/compose/.env | cut -d= -f2-); cat > /tmp/w.sh <<'EOF'
curl -s -u ditto:$DITTO_PASSWORD localhost:8080/api/2/things/kz.bozshakol:control/features | python3 -c "import json,sys;d=json.load(sys.stdin);print(json.dumps(d,ensure_ascii=False)[:800])"
curl -s -u ditto:$DITTO_PASSWORD localhost:8080/api/2/things/kz.bozshakol:whatif/features | python3 -c "
import json,sys;d=json.load(sys.stdin)
def walk(o,p=''):
  if isinstance(o,dict):
    for k,v in o.items(): walk(v,p+'/'+k)
  elif not isinstance(o,list):
    if any(s in p for s in ['scenario','status','exposed6','ore_short','delta_cu','cu_6m','updated','time']): print(p,o)
walk(d)"
EOF
bash /tmp/w.sh

